import subprocess
import psutil

def task_func(process_name: str) -> str:
    """
    Check if a process with the given name is running.
    If it is, terminate it, restart it, and return
    'Process found. Restarting <process_name>.'.
    If it is not running, start it and return
    'Process not found. Starting <process_name>.'.
    """
    # Find all running processes with the exact name
    running_procs = []
    for proc in psutil.process_iter(['name']):
        try:
            if proc.info['name'] == process_name:
                running_procs.append(proc)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    if running_procs:
        # Terminate all found instances
        for proc in running_procs:
            try:
                proc.terminate()
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue

        # Wait for termination (give a short timeout)
        for proc in running_procs:
            try:
                proc.wait(timeout=5)
            except psutil.TimeoutExpired:
                # If still alive, force kill
                try:
                    proc.kill()
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass

        # Restart the process
        try:
            subprocess.Popen(process_name, shell=True)
        except Exception as e:
            return f'Process found. Restarting {process_name}. (Failed to restart: {e})'

        return f'Process found. Restarting {process_name}.'

    else:
        # Process not running – start it
        try:
            subprocess.Popen(process_name, shell=True)
        except Exception as e:
            return f'Process not found. Starting {process_name}. (Failed to start: {e})'

        return f'Process not found. Starting {process_name}.'

